<script setup lang="ts">
import { computed, ref, onMounted, onUnmounted } from 'vue'
import { useRoute } from 'vue-router'
import NetworkResults from './NetworkResults.vue'
import SubdomainResults from './SubdomainResults.vue'
import { api } from './api'
const route=useRoute(),run=ref<Record<string,any>>(),error=ref(''),busy=ref(false),now=ref(Date.now())
const dns=computed(()=>run.value?.config_snapshot.mode==='subdomain')
const preparingScope=computed(()=>run.value&&!dns.value&&run.value.current_stage==='scope'&&['queued','running','pausing'].includes(run.value.status))
let timer:ReturnType<typeof setInterval>
async function load(){try{run.value=await api(`/runs/${route.params.runId}`);now.value=Date.now()}catch(e){error.value=(e as Error).message}}
onMounted(()=>{void load();timer=setInterval(()=>void load(),2500)})
onUnmounted(()=>clearInterval(timer))
const elapsed=computed(()=>{if(!run.value?.started_at)return 'Not started';const seconds=Math.max(0,Math.floor(((run.value.ended_at?Date.parse(run.value.ended_at):now.value)-Date.parse(run.value.started_at))/1000));return `${Math.floor(seconds/60)}m ${seconds%60}s`})
async function action(action:string){if(action==='stop'&&!confirm('Stop this run? Partial results will be preserved.'))return;busy.value=true;try{await api(`/runs/${route.params.runId}/${action}`,'POST');await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
</script>
<template><div class="page-heading"><div><p class="eyebrow">{{dns?'DNS ENUMERATION RESULTS':'NETWORK ASSESSMENT RESULTS'}}</p><h1>{{run?(dns?'Subdomain scan results':'Network scan results'):'Scan results'}}<span class="accent">.</span></h1><RouterLink :to="`/scans/${route.params.id}`">← Definition & history</RouterLink></div><div class="actions" v-if="run"><button class="subtle" v-if="run.status==='running'" :disabled="busy" @click="action('pause')">Pause</button><button v-if="run.status==='paused'" :disabled="busy" @click="action('resume')">Resume</button><button class="danger subtle" v-if="['queued','running','pausing','paused'].includes(run.status)" :disabled="busy" @click="action('stop')">Stop</button></div></div><p v-if="error" class="error" role="alert">{{error}}</p><template v-if="run"><section class="panel run-progress"><div class="actions"><span class="badge" :data-status="run.status">{{run.status}}</span><strong>{{run.current_stage}}</strong><span class="muted">{{elapsed}} · <template v-if="preparingScope">Preparing target scope</template><template v-else>{{run.processed}} / {{run.total}} {{dns?'names tested':'targets'}}</template></span></div><progress v-if="preparingScope" aria-label="DNS scope preparation"/><progress v-else :value="run.processed" :max="Math.max(1,run.total)" :aria-label="dns?'DNS wordlist progress':'Target progress'"/><p v-if="preparingScope" role="status" class="muted">Resolving hostnames and preparing the authorized IP scope. Scanning starts after this step completes.</p><p class="error" v-if="run.error_summary">{{run.error_summary}}</p><p class="muted" v-if="run.status==='pausing'">Waiting for the active subprocess to finish before pausing.</p></section><SubdomainResults v-if="dns" :key="run.id" :run="run"/><NetworkResults v-else :key="run.id" :run="run"/><details class="panel"><summary>Immutable approved configuration</summary><pre>{{JSON.stringify(run.config_snapshot,null,2)}}</pre></details></template></template>
